"""
    For a list, remove value in [" ",""]
    :param x(list): list of strings
    :returns empty_index: Index of empty String elements
    :returns x: Input list with empty element replaced with ".."
    """
def getMissingIndex(x: Any) -> object {
    empty_index = [
        i
        for (i, elem) in enumerate(x)
        if (elem in [" ", ""])
    ];
    for i in empty_index {
        x[i] = "..";
    }
    return (empty_index, x);
}

"""
    Returns True if the text "# Long" is in the first line of
    `raw_python_source`. False otherwise.
    """
def test_for_long_cell(raw_python_source: str) -> bool {
    first_element = raw_python_source.split("\n")[0];
    if (("#" in first_element) and ("long" in first_element.lower())) {
        return True;
    }
    return False;
}

"""
    Rescale the range of values of `x` from [input_min, input_max] -> [output_min, output_max].
    """
def rescale_values(
    x: Any,
    input_min: Any = -1,
    input_max: Any = 1,
    output_min: Any = 0,
    output_max: Any = 255
) -> object {
    assert (input_max > input_min);
    assert (output_max > output_min);
    return (
        (((x - input_min) * (output_max - output_min)) / (input_max - input_min))
        + output_min
    );
}

""" Return the least significant bit
    """
def least_significant_bit(val: Any) -> object {
    return ((val & -val).bit_length() - 1);
}
